('c0000000-0000-4000-8000-000000000060', 1, 'From standing, squat down and place your hands on the floor.'),
('c0000000-0000-4000-8000-000000000060', 2, 'Jump or step your feet back into a push-up position.'),
('c0000000-0000-4000-8000-000000000060', 3, 'Do a push-up if you want, then jump or step your feet back towards your hands.'),
('c0000000-0000-4000-8000-000000000060', 4, 'Stand up and jump, reaching your arms overhead.'),
('c0000000-0000-4000-8000-000000000061', 1, 'Start in a push-up position with your hands under your shoulders.'),
('c0000000-0000-4000-8000-000000000061', 2, 'Drive one knee towards your chest, then switch legs quickly.'),
('c0000000-0000-4000-8000-000000000061', 3, 'Keep alternating while holding a steady plank.'),
('c0000000-0000-4000-8000-000000000062', 1, 'Stand with your feet together and arms at your sides.'),
('c0000000-0000-4000-8000-000000000062', 2, 'Jump your feet out wide while raising your arms overhead.'),
('c0000000-0000-4000-8000-000000000062', 3, 'Jump back to the start and repeat at a steady rhythm.'),
('c0000000-0000-4000-8000-000000000063', 1, 'Pick up a heavy dumbbell or kettlebell in each hand with your palms facing in.'),
('c0000000-0000-4000-8000-000000000063', 2, 'Stand tall with your shoulders back and your core braced.'),
('c0000000-0000-4000-8000-000000000063', 3, 'Walk with short, steady steps for the set distance, then set the weights down carefully.');
