on conflict (id) do update set
  name = excluded.name,
  slug = excluded.slug,
  primary_muscle_group_id = excluded.primary_muscle_group_id,
  difficulty = excluded.difficulty,
  image_path = excluded.image_path,
  suggested_sets = excluded.suggested_sets,
  suggested_reps = excluded.suggested_reps,
  description = excluded.description,
  tracking_type = excluded.tracking_type,
  cues = excluded.cues,
  default_rest_seconds = excluded.default_rest_seconds;

-- Replace steps, equipment links and secondary muscles for the catalogue exercises.
delete from public.exercise_steps where exercise_id in (select id from public.exercises where owner_user_id is null and id::text like 'c0000000-0000-4000-8000-%');
delete from public.exercise_equipment where exercise_id in (select id from public.exercises where owner_user_id is null and id::text like 'c0000000-0000-4000-8000-%');
delete from public.exercise_secondary_muscles where exercise_id in (select id from public.exercises where owner_user_id is null and id::text like 'c0000000-0000-4000-8000-%');



